def backfill_dedupe_keys(apps, schema_editor):
    """给已有的待处理举报补去重键。

    历史数据里同一对用户可能已有重复的 pending 记录;唯一约束允许多个 NULL,
    因此每对只补最早的一条,其余保持 NULL,不会因为回填而迁移失败。

    Args:
        apps: 迁移时的应用注册表。
        schema_editor: 数据库 schema 编辑器(本函数不使用)。
    """
    Report = apps.get_model("moderation", "Report")
    seen = set()
    for report in Report.objects.filter(status="pending").order_by("created_at", "id"):
        key = f"{report.reporter_id}:{report.target_id}:pending"
        if key in seen:
            continue
        seen.add(key)
        Report.objects.filter(pk=report.pk).update(dedupe_key=key)


def clear_dedupe_keys(apps, schema_editor):
    """回滚时清空去重键。

    Args:
        apps: 迁移时的应用注册表。
        schema_editor: 数据库 schema 编辑器(本函数不使用)。
    """
    Report = apps.get_model("moderation", "Report")
    Report.objects.update(dedupe_key=None)


